/* =========================================================================
   hon-data.js — じどう車の 本（#/hon/<id>）の 中身

   ■ なにに つかうか
     「じどう車ずかんを つくろう」で、子どもが 図書室の 図鑑の かわりに 読む ページ。
     読んで、しごとの 文に あおペン、つくりの 文に みどりペンで 線を ひき、
     メモに あつめて から ノートに 書く。

   ■ 書きかたの きまり（tools/check-hon.mjs と selftest.html が たしかめる）
     ・教科書の 型に しない。「その ために」「しごとを して います」は 書かない。
       どれが しごとで どれが つくりか、どう つながるかは 子どもが 見つける。
     ・しごと（k:'s'）・つくり（k:'t'）・その ほか（k:'o'＝大きさ・はたらく 人・
       まめちしき）を まぜる。k は 画面には 出ない（本は こたえを 言わない）。
     ・1文だけ メモに うつされても 意味が とおる ように、主語を 入れる。
     ・分かち書き。漢字には ぜんぶ <ruby>漢字<rt>よみ</rt></ruby>。数字は 半角の 算用数字。
     ・part は car-art.js の data-part と おなじ 名まえ。「ここを 見て！」の
       ボタンに なり、おすと 絵の その ぶぶんが 光る。
     ・数は「やく」「くらい」の めやす。src に しらべた ところを 書く
       （画面では「せんせい・おうちの かたへ」の 中に 出る）。

   ■ 文を 書きかえた とき
     子どもが ひいた 線は 文の 文字から 作った かぎで ほぞんして いる。
     文を 1文字でも かえると、その 文の 線は 消える（ほかの 文に うつる ことは ない）。

   ■ ただしさ
     1台ずつ、消防・警察・自治体・メーカー などの 公式の しりょうで しらべて 書き、
     べつの 人が もう いちど しらべなおして います。まちがいを 見つけたら、
     src を たしかめて なおして ください。
   ========================================================================= */

